// Seller questions (SPEC §4.1, docs/design/wireframes.md §3), generated by CODE from the official Rev 20 description
// chains — never by the model:
//  (a) choice questions: the first chain level where the chosen candidates differ ("Which description matches the
//      item?"), options = those levels' official text (exhaustive siblings, so no "None of these"; the seller may be "Not sure",
//      which records nothing); then one level deeper inside the top
//      candidate's branch (at most 3 questions);
//  (b) exclusions: the other official lines under the top candidate's subheading, confirmed with one
//      "None of these apply to this item." checkbox.
// The seller's answers are statements; applySellerAnswers reruns the routing in code.
import type { HtsLine } from './hts';

export interface ChoiceQuestion {
  id: string;
  text: string;
  options: { id: string; text: string; codes: string[] }[];
}
export interface SellerQuestions {
  choices: ChoiceQuestion[];
  exclusions: { code: string; text: string }[];
}

const MAX_QUESTIONS = 3;
const MAX_EXCLUSIONS = 8;
const level = (s: string | undefined) => (s ?? '').trim().replace(/:$/, '');
const subheading = (code: string) => code.slice(0, 7); // "9102.21.70" → "9102.21"

/** `chosen`: the classifier's chosen codes, best first (all from the expanded official lines). */
export function buildQuestions(lines: readonly HtsLine[], chosen: readonly string[]): SellerQuestions {
  const chain = new Map(lines.map((l) => [l.code, l.chain.map(level)]));
  const top = chosen[0];
  const choices: ChoiceQuestion[] = [];
  let group = chosen.filter((c) => chain.has(c));
  while (top && group.length > 1 && choices.length < MAX_QUESTIONS) {
    const depth = Math.max(...group.map((c) => chain.get(c)!.length));
    let at = -1;
    for (let i = 0; i < depth; i++) {
      if (new Set(group.map((c) => chain.get(c)![i] ?? '')).size > 1) {
        at = i;
        break;
      }
    }
    if (at < 0) break; // identical chains: nothing a question could separate
    const byText = new Map<string, string[]>();
    for (const c of group) {
      const t = chain.get(c)![at];
      if (t) byText.set(t, [...(byText.get(t) ?? []), c]);
    }
    const parentOf = chain.get(group[0]!)!.slice(0, at);
    const options = [...byText].map(([text, codes], i) => ({ id: `o-${i}`, text: withSiblings(text, parentOf, at, lines), codes }));
    choices.push({ id: `level-${at}`, text: 'Which description matches the item?', options });
    group = options.find((o) => o.codes.includes(top))?.codes ?? [];
  }
  const topChain = top ? (chain.get(top) ?? []) : [];
  // A line that departs from the top line at a question's level, into one of that question's options (its official
  // level text), is already covered by the question — it isn't asked again as an exclusion.
  const covered = new Map<number, Set<string>>();
  for (const q of choices) {
    const at = Number(q.id.slice('level-'.length));
    covered.set(at, new Set(q.options.flatMap((o) => o.codes.map((c) => chain.get(c)![at]!))));
  }
  const exclusions = top
    ? lines
        .filter((l) => l.code.startsWith(subheading(top)) && !chosen.includes(l.code))
        .map((l) => ({ code: l.code, c: l.chain.map(level) }))
        .filter(({ c }) => {
          const at = c.findIndex((t, i) => t !== topChain[i]);
          return !(at >= 0 && covered.get(at)?.has(c[at]!));
        })
        .map(({ code, c }) => ({ code, text: exclusionText(c, topChain, lines) }))
        .slice(0, MAX_EXCLUSIONS)
    : [];
  return { choices, exclusions };
}

/**
 * An excluded line, read from the level where its chain departs from the top line's chain (official text only). A bare
 * "Other" at that level names the official sibling levels it is other than: "Other (not: A; B)".
 */
function exclusionText(c: string[], topChain: string[], lines: readonly HtsLine[]): string {
  let at = c.findIndex((t, i) => t !== topChain[i]);
  if (at < 0) at = c.length - 1;
  const tail = c.slice(at);
  tail[0] = withSiblings(tail[0] ?? '', c.slice(0, at), at, lines);
  return tail.join(' › ');
}

/** "Other" at a chain level → "Other (not: A; B)", naming the official sibling levels under the same parent. */
function withSiblings(text: string, parent: string[], at: number, lines: readonly HtsLine[]): string {
  if (!/^other$/i.test(text)) return text;
  const key = parent.join('\u0000');
  const siblings = [
    ...new Set(
      lines
        .map((l) => l.chain.map(level))
        .filter((x) => x.slice(0, at).join('\u0000') === key && x[at] && !/^other$/i.test(x[at]!))
        .map((x) => x[at]!),
    ),
  ];
  return siblings.length ? `${text} (not: ${siblings.join('; ')})` : text;
}

const CLEARED_BY_ANSWERS = new Set(['MISSING_ATTRIBUTES', 'TOP2_DIFFER_6']);

/**
 * answers: question id → option id (a question the seller is not sure about has no entry). exclusionsApply: true = the seller confirmed none of the excluded lines
 * apply; false = one of them applies; null = not answered. Answers only narrow the chosen codes; they never add one.
 */
export function applySellerAnswers(
  qs: SellerQuestions,
  answers: Record<string, string>,
  exclusionsApply: boolean | null,
  chosen: readonly string[],
  baseReasons: readonly string[],
): { reasons: string[]; needsReview: boolean; remaining: string[]; suggested: string | null } {
  let remaining = [...chosen];
  for (const [qid, oid] of Object.entries(answers)) {
    const q = qs.choices.find((x) => x.id === qid);
    if (!q) throw new Error(`unknown question ${qid}`);
    const asked = q.options.flatMap((o) => o.codes);
    // No "None of these": the official sibling levels are exhaustive. "Not sure" is simply no answer (no entry here).
    const opt = q.options.find((o) => o.id === oid);
    if (!opt) throw new Error(`unknown option ${oid} for ${qid}`);
    remaining = remaining.filter((c) => !asked.includes(c) || opt.codes.includes(c));
  }
  const top = chosen[0];
  const contradicts = (top !== undefined && !remaining.includes(top)) || exclusionsApply === false;
  const allAnswered = qs.choices.every((q) => answers[q.id] !== undefined) && (qs.exclusions.length === 0 || exclusionsApply !== null);
  let reasons = [...baseReasons];
  if (allAnswered && !contradicts) reasons = reasons.filter((r) => !CLEARED_BY_ANSWERS.has(r));
  if (contradicts && !reasons.includes('ANSWER_CONTRADICTS')) reasons.push('ANSWER_CONTRADICTS');
  const suggested = remaining.length === 1 && remaining[0] !== top ? remaining[0]! : null;
  return { reasons, needsReview: reasons.length > 0, remaining, suggested };
}
